<?php
namespace App\Filament\Resources;
use Filament\Resources\Resource;
use Filament\Schemas\Schema;
use Filament\Schemas\Components\Utilities\Get;
use Illuminate\Database\Eloquent\Builder;
use Filament\Tables\Table;
use Filament\Forms\Components\{TextInput,Textarea,Select,Toggle,DateTimePicker,DatePicker};
use Filament\Tables\Columns\TextColumn;
use Filament\Actions\EditAction;
class ScenarioResource extends Resource {
 protected static ?string $model=\App\Models\Scenario::class;
 protected static ?string $modelLabel='Scénarios';
 protected static ?string $pluralModelLabel='Scénarios';
 protected static string|\UnitEnum|null $navigationGroup='2 · Chiffrer';

 protected static ?int $navigationSort=10;

 public static function form(Schema $schema): Schema {return $schema->columns(2)->components([Select::make('event_project_id')->label('Édition')->relationship('eventProject','name')->live()->searchable()->preload()->required()->disabledOn('edit'),Toggle::make('is_archived')->label('Scénario archivé, exclu du lancement'),Toggle::make('furniture_paid_by_participant')->label('Mobilier à la charge des participants, location privilégiée'),TextInput::make('name')->label('Format')->maxLength(255)->required(),Toggle::make('launch_model')->label('Appliquer les règles de lancement et de préfinancement'),Select::make('parent_id')->label('Palier précédent à préserver')->relationship('parent','name',fn($query,Get $get)=>$query->where('event_project_id',$get('event_project_id'))),TextInput::make('event_days')->label('Jours d’événement')->integer()->minValue(1)->maxValue(31),TextInput::make('minimum_daily_activities')->label('Épreuves distinctes minimum / jour')->integer()->minValue(3)->maxValue(30)->default(3),TextInput::make('independent_target')->label('Stands indépendants')->integer()->minValue(0)->maxValue(1000)->default(6),TextInput::make('guests_per_stand')->label('Hypothèse de public simultané par stand')->integer()->minValue(1)->maxValue(10000),Select::make('shelter_model')->label('Accueil abrité')->options(['common'=>'Chapiteau commun (historique)','distributed'=>'Tentes conviviales par stand'])->default('common')->required(),TextInput::make('tent_capacity')->label('Capacité étudiée du chapiteau')->integer()->minValue(1)->maxValue(100000),TextInput::make('contingency_cents')->label('Réserve imprévus (centimes, vide = inconnu)')->integer()->minValue(0)->maxValue(1000000000),TextInput::make('refund_reserve_cents')->label('Réserve remboursements / annulation (centimes)')->integer()->minValue(0)->maxValue(1000000000),Textarea::make('reserve_evidence')->label('Hypothèses et justification des réserves')->maxLength(5000),Select::make('includedStands')->label('Unités stand de ce scénario')->multiple()->relationship('includedStands','name',fn($query,Get $get)=>$query->where('event_project_id',$get('event_project_id')))->preload(),Select::make('includedFeatures')->label('Équipements du site dont les besoins sont chiffrés ici')->multiple()->relationship('includedFeatures','name',fn($query,Get $get)=>$query->where('event_project_id',$get('event_project_id')))->preload()->helperText('Ne pas recopier ces besoins dans les lignes budgétaires.'),TextInput::make('months')->label('Mois de travail')->integer()->minValue(0)->maxValue(1000000000)->minValue(1)->maxValue(36)->required()->default(1),TextInput::make('target_surplus_cents')->label('Objectif QAPAS par mois (centimes)')->integer()->minValue(0)->maxValue(1000000000)->required()->default(400000),TextInput::make('organizer_net_monthly_cents')->label('Rémunération nette mensuelle prévue (centimes)')->integer()->minValue(0)->maxValue(1000000000)->required()->default(100000),TextInput::make('organizer_full_monthly_cents')->label('Coût mensuel COMPLET avec charges (centimes)')->integer()->minValue(0)->maxValue(1000000000)->gte('organizer_net_monthly_cents')->helperText('À obtenir du comptable ; ne pas ajouter une seconde ligne de rémunération au budget.'),TextInput::make('minimum_organizer_charges_cents')->label('Charges minimales à couvrir pour l’édition (centimes)')->integer()->minValue(0)->default(80000),Textarea::make('organizer_cost_evidence')->label('Période, frais sociaux réels et absence de double comptage')->helperText('Le calcul retient le plus grand du coût complet mensuel × mois et de ce plancher, sans les additionner.'),TextInput::make('team_target')->label('Équipes envisagées')->integer()->minValue(0)->maxValue(1000000000)->required()->default(0),TextInput::make('stand_target')->label('Stands envisagés')->integer()->minValue(0)->maxValue(1000000000)->required()->default(0),Toggle::make('costs_complete')->label('Tous les coûts de ce scénario ont été recensés')->default(false),Select::make('includedActivities')->label('Épreuves dont le matériel entre dans ce scénario')->multiple()->relationship('includedActivities','name',fn(Builder $query,Get $get)=>$query->where('event_project_id',$get('event_project_id'))->where('status','!=','archived'))->preload()->rules([fn(Get $get)=>\Illuminate\Validation\Rule::exists('activities','id')->where('event_project_id',$get('event_project_id'))])->helperText('Coûts repris directement. Ne pas recopier le même matériel dans les lignes budgétaires.')->columnSpanFull(),Textarea::make('assumptions')->label('Hypothèses, exclusions et incertitudes')->maxLength(10000)->rows(3)->columnSpanFull()]);}
 public static function table(Table $table): Table {return $table->columns([TextColumn::make('name')->label('Nom')->searchable()->wrap(),TextColumn::make('eventProject.name')->label('Édition'),TextColumn::make('months')->label('Mois'),TextColumn::make('updated_at')->label('Mise à jour')->dateTime('d/m/Y H:i')->sortable()])->filters([\Filament\Tables\Filters\TernaryFilter::make('is_archived')->label('Archives')->placeholder('Tous')->trueLabel('Archives uniquement')->falseLabel('Scénarios actifs')->default(false)])->defaultSort('updated_at','desc')->recordActions([\Filament\Actions\Action::make('costing')->label('Chiffrer')->url(fn($record)=>static::getUrl('edit',['record'=>$record])),EditAction::make()]);}
 public static function getRelations(): array {return [\App\Filament\RelationManagers\CostsRelationManager::class,\App\Filament\RelationManagers\RevenuesRelationManager::class];}
 public static function getPages(): array {return ['index'=>\App\Filament\Resources\ScenarioResource\Pages\ManageRecords::route('/'),'edit'=>\App\Filament\Resources\ScenarioResource\Pages\EditRecord::route('/{record}/edit')];}
}
